<?php
declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';
$esc=static fn($v):string=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');
$pdo=db();$pk='id';try{$keys=$pdo->query("SHOW KEYS FROM projects WHERE Key_name='PRIMARY'")->fetchAll();if(!empty($keys[0]['Column_name']))$pk=(string)$keys[0]['Column_name'];}catch(Throwable $e){}
if($_SERVER['REQUEST_METHOD']==='POST'){$action=(string)($_POST['action']??'');$id=(int)($_POST['id']??0);if($id>0&&in_array($action,['delete','toggle','feature'],true)){if($action==='delete'){$stmt=$pdo->prepare("DELETE FROM projects WHERE `{$pk}`=?");$stmt->execute([$id]);}elseif($action==='toggle'){$pdo->prepare("UPDATE projects SET is_published=1-COALESCE(is_published,0) WHERE `{$pk}`=?")->execute([$id]);}else{$pdo->prepare("UPDATE projects SET is_featured=1-COALESCE(is_featured,0) WHERE `{$pk}`=?")->execute([$id]);}}header('Location: projects.php');exit;}
$q=trim((string)($_GET['q']??''));$category=trim((string)($_GET['category']??''));$status=(string)($_GET['status']??'');$where=[];$params=[];if($q!==''){$where[]='(title LIKE ? OR slug LIKE ? OR client_name LIKE ? OR category LIKE ?)';for($i=0;$i<4;$i++)$params[]='%'.$q.'%';}if($category!==''){$where[]='category=?';$params[]=$category;}if($status==='published'||$status==='draft'){$where[]='is_published=?';$params[]=$status==='published'?1:0;}$sql='SELECT * FROM projects'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY COALESCE(is_featured,0) DESC, sort_order ASC, created_at DESC';$stmt=$pdo->prepare($sql);$stmt->execute($params);$projects=$stmt->fetchAll();$categories=$pdo->query('SELECT DISTINCT category FROM projects WHERE category IS NOT NULL AND category<>\'\' ORDER BY category')->fetchAll(PDO::FETCH_COLUMN);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Projects | Admin</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><nav class="navbar navbar-dark bg-dark"><div class="container"><a class="navbar-brand fw-bold" href="dashboard.php">Distinguished Web Services</a><a class="btn btn-outline-light btn-sm" href="logout.php">Logout</a></div></nav><main class="container py-5"><div class="d-flex flex-wrap gap-3 justify-content-between align-items-center mb-4"><div><h1 class="h2 mb-1">Projects & Case Studies</h1><p class="text-muted mb-0"><?=count($projects)?> project(s) found</p></div><a href="project-form.php" class="btn btn-primary">+ Add Project</a></div><div class="card border-0 shadow-sm mb-4"><div class="card-body"><form class="row g-2"><div class="col-lg-5"><input name="q" class="form-control" value="<?=$esc($q)?>" placeholder="Search title, client, category or slug..."></div><div class="col-lg-3"><select name="category" class="form-select"><option value="">All categories</option><?php foreach($categories as $c):?><option value="<?=$esc($c)?>" <?=$category===$c?'selected':''?>><?=$esc($c)?></option><?php endforeach;?></select></div><div class="col-lg-2"><select name="status" class="form-select"><option value="">All statuses</option><option value="published" <?=$status==='published'?'selected':''?>>Published</option><option value="draft" <?=$status==='draft'?'selected':''?>>Draft</option></select></div><div class="col-lg-2 d-flex gap-2"><button class="btn btn-dark flex-fill">Filter</button><a href="projects.php" class="btn btn-outline-secondary">Reset</a></div></form></div></div><div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table align-middle mb-0"><thead class="table-light"><tr><th>Project</th><th>Category</th><th>Featured</th><th>Status</th><th class="text-end">Actions</th></tr></thead><tbody><?php foreach($projects as $p):$pid=(int)($p[$pk]??0);?><tr><td><strong><?=$esc($p['title']??'')?></strong><div class="small text-muted">/case-study.php?slug=<?=$esc($p['slug']??'')?></div></td><td><?=$esc($p['category']??'')?></td><td><span class="badge <?=((int)($p['is_featured']??0)?'text-bg-warning':'text-bg-light')?>"><?=((int)($p['is_featured']??0)?'Featured':'Standard')?></span></td><td><span class="badge <?=((int)($p['is_published']??0)?'text-bg-success':'text-bg-secondary')?>"><?=((int)($p['is_published']??0)?'Published':'Draft')?></span></td><td class="text-end text-nowrap"><a class="btn btn-sm btn-outline-primary" href="project-form.php?id=<?=$pid?>">Edit</a><a class="btn btn-sm btn-outline-dark" target="_blank" rel="noopener" href="../case-study.php?slug=<?=$esc($p['slug']??'')?>">Preview</a><form method="post" class="d-inline"><input type="hidden" name="action" value="feature"><input type="hidden" name="id" value="<?=$pid?>"><button class="btn btn-sm btn-outline-warning">Feature</button></form><form method="post" class="d-inline"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$pid?>"><button class="btn btn-sm btn-outline-secondary"><?=((int)($p['is_published']??0)?'Draft':'Publish')?></button></form><form method="post" class="d-inline" onsubmit="return confirm('Delete this project and its case-study record?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$pid?>"><button class="btn btn-sm btn-outline-danger">Delete</button></form></td></tr><?php endforeach;if(!$projects):?><tr><td colspan="5" class="text-center text-muted py-5">No projects match your filters.</td></tr><?php endif;?></tbody></table></div></div></main></body></html>